    ["SkillConfig/10/showName"] = "Ion Burst",
    ["SkillConfig/10071/des"] = "Basic Attack deals #48b6e50.7 x MATK + 10#E Magic DMG. Perform a Special Basic Attack every 4s, dealing #48b6e52 x MATK + 20#E Magic DMG to all targets hit.",
    ["SkillConfig/10071/showName\nSkillConfig/10181/showName"] = "Fireball",
