    ["SkillConfig/10072/showName"] = "Sacrificial Flame",
    ["SkillConfig/10073/des"] = "Blink to the area with the most enemies and release a ring of fire, dealing #48b6e51 x MATK#E Magic DMG. Then, return and deal #48b6e52 x MATK + 25#E Magic DMG.",
    ["SkillConfig/10073/showName"] = "Queen's Wrath",
    ["SkillConfig/10081/des"] = "Basic Attack deals #48b6e50.7 x MATK + 10#E Magic DMG. Perform a Special Basic Attack every 4 attacks, dealing area damage and restoring #48b6e52#E Mana.",
    ["SkillConfig/10081/showName"] = "Water Bolt",
    ["SkillConfig/10082/des"] = "Restore #995ebc2#E additional Mana per second.",
    ["SkillConfig/10082/showName"] = "Pressure Feedback",
    ["SkillConfig/10083/des"] = "Create a water orb at the target location. The water orb explodes, dealing #48b6e52 x MATK + 120#E Magic DMG to all targets within range. Ultimate gain #48b6e533%#E Damage Up after each Ultimate cast, up to 4 times.",
    ["SkillConfig/10083/showName"] = "Water Burial",
    ["SkillConfig/10091/des"] = "Basic Attack deals 1 x #f2783dPATK#E Phy DMG. Attack twice on #fac21bCrit#E, with each attack dealing 0.6 x #f2783dPATK#E Phy DMG with #fac21bguaranteed Crit#E.",
    ["SkillConfig/10091/showName"] = "Gale Arrow",
    ["SkillConfig/10092/des"] = "At 50% HP or above, gain 10% #fac21bCrit#E Rate. At less than 50% HP, gain 10% #d8c09fEvasion#E Rate.",
    ["SkillConfig/10092/showName"] = "Soothe Mind",
    ["SkillConfig/10093/des"] = "Activate Precision Mode, and attacks now hit 3 additional targets, lasting 3s.",
    ["SkillConfig/10093/showName"] = "Splitting Gale",
    ["SkillConfig/101/showName"] = "Base Self-Destruct",
    ["SkillConfig/10101/des"] = "Basic Attack deals #f2783d0.7 x PATK + 10#E Phy DMG. Perform 2 Special Basic Attacks every 6s, dealing #f2783d0.5 x PATK#E + #47bd5c3% x Max HP#E area Phy DMG.",
    ["SkillConfig/10101/showName"] = "Lucky Strike",
    ["SkillConfig/10102/des"] = "Increase #47bd5cMax HP#E by 15%.",
    ["SkillConfig/10102/showName"] = "Elegant Dance",
    ["SkillConfig/10103/des"] = "Strike the ground rapidly, attacking 3 times. The first two strikes deal #47bd5c1% x Max HP + 50#E Phy DMG in a small area, and the final strike deals #47bd5c4% x Max HP + 70#E Phy DMG to the enemy.",
    ["SkillConfig/10103/showName"] = "Unleash Life",
    ["SkillConfig/10111/des"] = "Basic Attack deals #f2783d1.2 x PATK#E Phy DMG. Every Basic Attack has a #f2783d0.1% x Assassin's Soul Stack + 10%#E chance to release a Whirling Blade, dealing #f2783d1 x PATK#E area Phy DMG.",
    ["SkillConfig/10111/showName"] = "Whirling Blade",
    ["SkillConfig/10112/des"] = "Gain 1, 10, and 5 Assassin's Soul stacks from Basic Attack, Ultimate cast, and on kill, respectively. At 20, 50, and 100 stack, Assassin's Soul grants #f2783d10% PATK#E, #e23b3b20% Damage Reduction#E, and #f2783d20% Basic Attack Leech#E. Reset every round.",
    ["SkillConfig/10112/showName\nEffectConfig/101127/showName\nEffectConfig/101128/showName\nEffectConfig/101129/showName"] = "Assassin's Soul",
    ["SkillConfig/10113/des"] = "Leave an Assassin Simulacrum that performs Basic Attacks at the original location. If there are enemies within 600-2000 units, teleport behind the farthest enemy and attack. If not, become Berserk, gaining #e639d220% ATK SPD#E and #f2783d10% PATK#E for 4s. The Assassin Simulacrum inherits #47bd5c50% Max HP#E, #f2783d70% PATK#E, and #f2783d100% Assassin's Soul#E. When the Assassin Simulacrum is killed or after 8s, return to the original position.",
    ["SkillConfig/10113/showName"] = "Assassin Simulacrum",
    ["SkillConfig/10121/des"] = "Basic Attacks deal (0.8 x MATK + 10) Magic DMG. Every Basic Attack has a (0.25% x MATK + 10%) chance to cast Venom Overwhelm, dealing (0.8 x MATK + 20) Magic DMG to up to 4 units within 400 units. If the enemy's MATK  less than you, Venom Overwhelm applies 40 Poison stacks.",
    ["SkillConfig/10121/showName"] = "Venom Overwhelm",
    ["SkillConfig/10122/des"] = "Release Smog every 10s, applying (2 x Level) Poison stacks to units within 800 units. Units within 400-550 units receive an additional (3 x Level + 10) Poison stacks. Units within 400 units receive an additional (4 x Level + 20) Poison stacks.",
    ["SkillConfig/10122/showName"] = "Venom Miasma",
    ["SkillConfig/10123/des"] = "Launch a Venom Chain, dealing Magic DMG to up to 5 units. The primary target takes (100 + 1 x Poison Stack) Magic DMG, and the secondary targets take (80 + 0.3 x Poison Stack) Magic DMG. After being hit, the target receives an additional 40 Poison stacks.",
    ["SkillConfig/10123/showName"] = "Venom Chain",
    ["SkillConfig/10131/des"] = "Deal 80% ATK Magic DMG.",
    ["SkillConfig/10131/showName"] = "Basic Attack",
    ["SkillConfig/10132/des"] = "Restore 5 Mana on kill.",
    ["SkillConfig/10132/showName\nSkillConfig/10224/showName\nSkillConfig/10225/showName\nSkillConfig/10226/showName\nSkillConfig/10227/showName"] = "Passive",
    ["SkillConfig/10133/des"] = "Fire streams of missiles on random targets for 1s, firing a missile every 0.1s. Missile deal 20% ATK Magic DMG on hit. Ultimate kill permanently extend Ultimate duration by 0.1s, and Hero kill extend it by 0.5s instead.",
    ["SkillConfig/10133/showName"] = "Ultimate",
    ["SkillConfig/10141/des"] = "Basic Attack deals #f2783d0.6 x PATK + 15#E Phy DMG. Perform a Special Basic Attack every 5s, dealing a bonus #4398ef0.8 x MDEF + 50#E area Magic DMG.",
    ["SkillConfig/10141/showName"] = "Taiji Duality",
    ["SkillConfig/10142/des"] = "#10d1a620%#E of the Phy DMG taken is converted into Magic DMG, and #10d1a6heal#E for #10d1a610%#E of the damage converted.",
    ["SkillConfig/10142/showName"] = "Yin-Yang Harmony",
    ["SkillConfig/10143/des"] = "Deal #4398ef1.8 x MDEF + 60#E Magic DMG to the target. The greater the difference in #4398efMDEF#E with the target, the higher the damage, up to #4398ef300%#E. Restore #995ebc50#E Mana on kill.",
    ["SkillConfig/10143/showName"] = "Inksplash Creation",
    ["SkillConfig/10151/des"] = "Basic Attacks deal #f2783d0.5 x PATK#E Phy DMG. Lefty's Basic Attacks additionally deal #f2783d15#E fixed DMG. Righty additionally gains #a3775b10 Shield#E on Basic Attack.",
    ["SkillConfig/10152/des"] = "At the start of combat, charge at the enemy every 8s, knocking them up for 1s and dealing #a3775bShield/5s + 100#E Phy DMG.",
    ["SkillConfig/10152/showName"] = "Ironclad Slam",
    ["SkillConfig/10153/des"] = "Charge and immediately gain #a3775b2 x Level + 50 Shield#E. Once fully charged, deal #f2783d2 x Shield Lost During Charge + 150#E Phy DMG to all targets in a fan-shaped area.",
    ["SkillConfig/10161/des"] = "Basic Attacks deal #f2783d0.5 x PATK+10#E Phy DMG. Perform a Special Basic Attack every 4 attacks, dealing #f2783d0.6 x PATK#E+ #f2783d100 x Evasion Rate#E area Phy DMG that is guaranteed to hit and gaining Evasion by 20% for 2s.",
    ["SkillConfig/10161/showName"] = "Pugilist Strike",
    ["SkillConfig/10162/des"] = "Gain 2 Smolder stacks on successful Evasion, and gain a Smolder stack on taking damage, up to 50 stacks. At 25 stacks, gain #d8c09f20%#E Evasion Rate. At 50 stacks, gain #fac21b20%#E Crit. Expire after this round ends.",
    ["SkillConfig/10162/showName\nEffectConfig/101624/showName\nEffectConfig/101625/showName\nEffectConfig/101626/showName"] = "Smolder",
    ["SkillConfig/10163/des"] = "Kick the enemy, dealing #d8c09f100 x Evasion Rate + 50#E Phy DMG. Then, perform a 3-combo attack, dealing #d8c09f20 x Evasion Rate + 15#E Phy DMG 3 times. Finally, kick the enemy high again after landing, dealing #d8c09f300 x Evasion Rate + 50#E Phy DMG.",
    ["SkillConfig/10163/showName"] = "Chain Flying Kick",
    ["SkillConfig/10171/des"] = "Basic Attacks hit enemies with a spatula, dealing #47bd5c1% x Max HP + 20#E Phy DMG. Perform a Special Basic Attack every 5s, dealing #47bd5c2% x Max HP + 25#E Phy DMG to enemies in a straight line. The larger the size, the bigger the attack area.",
    ["SkillConfig/10171/showName"] = "Spatula & Cleaver",
    ["SkillConfig/10172/des"] = "Gain a Gluttony stack for every 100 Crystals consumed. Gain #47bd5c0.5%#E Size and #47bd5c0.2% Max HP#E for each Gluttony stack, up to 100 stacks.",
    ["SkillConfig/10172/showName\nEffectConfig/101721/showName\nEffectConfig/101724/showName"] = "Feast of Gluttony",
    ["SkillConfig/10173/des"] = "Spin and dash towards the area with the most enemies within 1000 units, dealing #f2783d1.5 x Level + 8#E Phy DMG 6 times along the way. The last hit deals #47bd5c5% x Max HP + 20#E area Fixed DMG. The larger the size, the bigger the attack area of Rampage.",
    ["SkillConfig/10173/showName"] = "Rampaging Spatula",
    ["SkillConfig/10181/des"] = "Basic Attacks deal #48b6e50.4 x MATK + 5#E Magic DMG. Perform a Special Basic Attack every 8 attacks, launching a bouncing flame chain that deals #48b6e51.5 x MATK#E Magic DMG, bouncing up to 4 targets.",
    ["SkillConfig/10182/des"] = "Gain a Dominance stack for each unit summoned. Gain #48b6e51#E #48b6e5MATK#E permanently for every 5 Dominance stacks, up to #48b6e5200#E stacks.",
    ["SkillConfig/10182/showName\nEffectConfig/101824/showName\nEffectConfig/101825/showName\nEffectConfig/101826/showName"] = "Dominance",
    ["SkillConfig/10183/des"] = "Summon 3 Vipers behind. Vipers perform a bouncing attack #48b6e5up to 4 targets, with damage decreasing by 15% each bounce#E, dealing #48b6e50.2 x Jiggs MATK + 3#E Magic DMG. Vipers last 6s, with a cap of 12 Vipers at a time.",
    ["SkillConfig/10183/showName"] = "Serpent Staff",
    ["SkillConfig/10184/des"] = "Deals #48b6e50.2 x Jiggs MATK + 3#E Magic DMG.",
    ["SkillConfig/10184/showName"] = "Bouncing Flame",
    ["SkillConfig/10191/des"] = "Basic Attacks deal #f2783d0.6 x PATK + 10#E Phy DMG. After every 3 Basic Attacks, perform a Special Basic Attack, unleashing a hurricane that knocks up enemies along the path and deals #f2783d3 x Level + 20#E Fixed DMG. Enemies knocked up are marked by the Hurricane Mark and take an additional #f2783d20%#E damage. Marked enemies #f2783dcannot be knocked up#E.",
    ["SkillConfig/10191/showName"] = "Hurricane Slash",
    ["SkillConfig/10192/des"] = "Cast Wind Slash at enemies with Hurricane Mark every 10s, dealing #f2783d6 x Level + 20#E Fixed DMG to enemies along the path, healing for #10d1a62 x Level#E HP, and removing the Hurricane Mark. While under this state, no hurricanes will be unleashed and can cast Wind Slash up to 6 times.",
    ["SkillConfig/10192/showName"] = "Wind Slash",
    ["SkillConfig/10193/des"] = "Gain #f2783d20%#E PATK, #e639d220%#E ATK SPD, and #10d1a620%#E Damage Reduction for 4s.",
    ["SkillConfig/10193/showName\nEffectConfig/101931/showName"] = "Serenity",
    ["SkillConfig/102/showName"] = "Generic Melee",
    ["SkillConfig/10201/des"] = "Deal #f2783d0.2 x PATK + 10#E Phy DMG to the target 5 times. Perform a Special Basic Attack every 5s, dealing #f2783d3 x Level + 20#E area Phy DMG and applying a Bleed stack.",
    ["SkillConfig/10201/showName"] = "Yo-Yo",
    ["SkillConfig/10202/des"] = "15s after the combat starts, summon a Dire Wolf Projection. The Dire Wolf cannot be targeted and hunts the unit with the lowest HP percentage. The Dire Wolf's attacks heal Lily for #10d1a62 x Level + 12#E HP. If the target is bleeding, the healing is doubled.",
